(() => {
  const get=async u=>{const r=await fetch(u);const d=await r.json();if(!r.ok)throw Error(d.error||'Error');return d};
  const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button=(label,id,status,type)=>'<button class="secondary" data-kind="'+type+'" data-id="'+id+'" data-status="'+status+'" style="width:auto;padding:8px 10px;margin:4px">'+label+'</button>';
  async function loadOps(){
    try{const me=await get('/api/me');if(!['owner','admin'].includes(me.staff.role))return;document.getElementById('operations').hidden=false;
      const bookings=await get('/api/bookings');document.getElementById('bookingList').innerHTML=bookings.bookings.map(b=>'<div class="guest booking-card"><b>'+esc(b.resource_name)+'</b> · '+esc(b.full_name)+'<br>'+esc(b.start_date)+' a '+esc(b.end_date)+' · '+esc(b.guests||'—')+' personas · '+esc(b.phone)+'<br><span class="status status-'+esc(b.status)+'">'+esc(b.status)+'</span><div>'+button('Confirmar',b.id,'confirmed','booking')+button('Cancelar',b.id,'cancelled','booking')+'</div></div>').join('')||'<p class="message">No hay solicitudes.</p>';
      const reviews=await get('/api/reviews');document.getElementById('reviewList').innerHTML=reviews.reviews.filter(r=>r.status==='pending').map(r=>'<div class="guest"><b>'+esc(r.full_name)+'</b> · '+('★'.repeat(r.rating))+'<br>'+esc(r.comment)+'<div>'+button('Publicar',r.id,'approved','review')+button('Rechazar',r.id,'rejected','review')+'</div></div>').join('')||'<p class="message">No hay opiniones pendientes.</p>';
      document.querySelectorAll('[data-kind]').forEach(x=>x.onclick=async()=>{await fetch('/api/'+x.dataset.kind+'s/'+x.dataset.id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status:x.dataset.status})});loadOps()});
    }catch{}
  }
  async function addCabinEditor(){try{const me=await get('/api/me');if(!['owner','admin'].includes(me.staff.role))return;const host=document.getElementById('operations');const editor=document.createElement('section');editor.className='card';editor.innerHTML='<h2>Editar cabaña</h2><p class="message">Actualiza precios, capacidad, piscina y descripción. Los cambios quedan listos para publicarse en las fichas.</p><form id="cabinForm" class="admin-grid"><input name="slug" placeholder="Código, ej. boldo" required><input name="display_name" placeholder="Nombre visible" required><input name="low_price" type="number" placeholder="Precio temporada baja"><input name="high_price" type="number" placeholder="Precio temporada alta"><input name="guests" type="number" placeholder="Capacidad"><input name="bedrooms" type="number" placeholder="Dormitorios"><select name="pool_type"><option value="">Piscina</option><option>propia</option><option>compartida</option></select><input name="description" placeholder="Descripción breve"><button class="primary">Guardar cabaña</button></form><p id="cabinMessage" class="message"></p><a class="secondary" style="display:inline-block;text-decoration:none;margin-top:14px" href="/api/exports/visits">Descargar ingresos CSV</a>';host.after(editor);editor.querySelector('#cabinForm').onsubmit=async e=>{e.preventDefault();const r=await fetch('/api/cabins',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const d=await r.json();editor.querySelector('#cabinMessage').textContent=r.ok?'Cabaña guardada.':d.error||'Error'};}catch{}}
  async function addControls(){try{const me=await get('/api/me');const host=document.getElementById('operations');const card=document.createElement('section');card.className='card';card.innerHTML='<h2>Mi seguridad</h2><form id="pinForm" class="admin-grid"><input name="current_pin" type="password" placeholder="PIN actual" required><input name="new_pin" type="password" placeholder="Nuevo PIN (6+ caracteres)" required><button class="primary">Cambiar PIN</button></form><p id="pinMessage" class="message"></p>';host.after(card);card.querySelector('#pinForm').onsubmit=async e=>{e.preventDefault();const r=await fetch('/api/change-pin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});const d=await r.json();card.querySelector('#pinMessage').textContent=r.ok?'PIN actualizado.':d.error||'Error'};if(['owner','admin'].includes(me.staff.role)){const n=await get('/api/notifications');const box=document.createElement('section');box.className='card';box.innerHTML='<h2>Notificaciones</h2><div>'+n.notifications.filter(x=>!x.is_read).map(x=>'<div class="guest"><b>'+esc(x.title)+'</b><br>'+esc(x.detail)+'</div>').join('')+'</div><a class="secondary" style="display:inline-block;text-decoration:none;margin:8px" href="/api/exports/bookings">Exportar reservas</a><a class="secondary" style="display:inline-block;text-decoration:none;margin:8px" href="/api/exports/reviews">Exportar opiniones</a>';card.after(box)}}catch{}}
  async function addOwnerTools(){try{const me=await get('/api/me');if(me.staff.role!=='owner')return;const host=document.getElementById('operations'),box=document.createElement('section');box.className='card';const team=await get('/api/staff');box.innerHTML='<h2>Permisos del equipo</h2><p class="message">El dueño define rol y acceso activo de cada integrante.</p>'+team.staff.filter(x=>x.id!==me.staff.id).map(x=>'<div class="guest"><b>'+esc(x.full_name)+'</b> · '+esc(x.email)+'<br><select data-role="'+x.id+'"><option value="receptionist" '+(x.role==='receptionist'?'selected':'')+'>Recepcionista</option><option value="admin" '+(x.role==='admin'?'selected':'')+'>Administrador</option></select> <label><input type="checkbox" data-active="'+x.id+'" '+(x.active?'checked':'')+'> Activo</label> <button data-save="'+x.id+'" class="secondary" style="width:auto">Guardar</button></div>').join('');host.after(box);box.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{const id=b.dataset.save,role=box.querySelector('[data-role="'+id+'"]').value,active=box.querySelector('[data-active="'+id+'"]').checked;await fetch('/api/staff/'+id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({role,active,permissions:[]})});b.textContent='Guardado'});}catch{}}
  async function addHistory(){try{const me=await get('/api/me');if(!['owner','admin'].includes(me.staff.role))return;const host=document.getElementById('operations'),box=document.createElement('section');box.className='card';const a=await get('/api/audit');box.innerHTML='<h2>Historial de cambios</h2>'+a.events.map(x=>'<div class="guest"><b>'+esc(x.action)+'</b><br>'+esc(x.full_name||'Sistema')+' · '+esc(x.detail||'')+'<br><small>'+esc(x.created_at)+'</small></div>').join('');host.after(box)}catch{}}
  async function addPhotoEditor(){try{const me=await get('/api/me');if(!['owner','admin'].includes(me.staff.role))return;const host=document.getElementById('operations'),box=document.createElement('section');box.className='card';box.innerHTML='<h2>Galería de cabaña</h2><p class="message">Pega una URL por línea. Después se puede reemplazar por carga directa de fotos.</p><form id="photoForm" class="admin-grid"><input name="slug" placeholder="Código de cabaña, ej. boldo" required><input name="display_name" placeholder="Nombre de cabaña" required><textarea name="photo_urls" style="min-height:110px" placeholder="https://...foto-1.jpg&#10;https://...foto-2.jpg"></textarea><button class="primary">Guardar galería</button></form><p id="photoMessage" class="message"></p>';host.after(box);box.querySelector('#photoForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.photo_urls=b.photo_urls.split('\n').map(x=>x.trim()).filter(Boolean);const r=await fetch('/api/cabins',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});const d=await r.json();box.querySelector('#photoMessage').textContent=r.ok?'Galería guardada.':d.error||'Error'};}catch{}}
  async function addReservationFilters(){try{const me=await get('/api/me');if(!['owner','admin'].includes(me.staff.role))return;const host=document.getElementById('operations'),box=document.createElement('section');box.className='card';const d=await get('/api/bookings');box.innerHTML='<h2>Buscar reservas</h2><select id="bookingState"><option value="">Todos los estados</option><option value="pending">Pendientes</option><option value="confirmed">Confirmadas</option><option value="cancelled">Canceladas</option></select> <input id="bookingDate" type="date"><div id="bookingResults"></div>';const draw=()=>{const state=box.querySelector('#bookingState').value,date=box.querySelector('#bookingDate').value;box.querySelector('#bookingResults').innerHTML=d.bookings.filter(x=>(!state||x.status===state)&&(!date||x.start_date===date||x.end_date===date)).map(x=>'<div class="guest"><b>'+esc(x.resource_name)+'</b> · '+esc(x.full_name)+'<br>'+esc(x.start_date)+' a '+esc(x.end_date)+' · '+esc(x.status)+'</div>').join('')||'<p class="message">Sin resultados.</p>'};box.querySelector('#bookingState').onchange=draw;box.querySelector('#bookingDate').onchange=draw;draw();host.after(box)}catch{}}
  async function addDashboard(){try{const me=await get('/api/me');if(!['owner','admin'].includes(me.staff.role))return;const host=document.getElementById('operations');const [v,b,r]=await Promise.all([get('/api/visits?limit=200'),get('/api/bookings'),get('/api/reviews')]);const box=document.createElement('section');box.className='card';box.innerHTML='<h2>Resumen operativo</h2><div class="admin-grid"><div class="guest"><b>'+v.visits.length+'</b><br>Ingresos recientes</div><div class="guest"><b>'+b.bookings.filter(x=>x.status==='pending').length+'</b><br>Reservas pendientes</div><div class="guest"><b>'+r.reviews.filter(x=>x.status==='pending').length+'</b><br>Opiniones pendientes</div></div><a class="secondary" style="display:inline-block;text-decoration:none;margin-top:14px" target="_blank" href="/api/exports/report">Abrir reporte para PDF</a>';host.after(box);const up=document.createElement('section');up.className='card';up.innerHTML='<h2>Subir foto de cabaña</h2><p class="message">Sube una imagen desde tu computador (máximo 8 MB). Después copia la dirección generada en la galería de la cabaña que corresponda.</p><form id="uploadForm"><input type="file" name="file" accept="image/*" required><button class="primary">Subir foto</button></form><p id="uploadMessage" class="message"></p>';box.after(up);up.querySelector('#uploadForm').onsubmit=async e=>{e.preventDefault();const res=await fetch('/api/uploads',{method:'POST',body:new FormData(e.target)}),d=await res.json();up.querySelector('#uploadMessage').textContent=res.ok?'Foto subida. Copia esta dirección: '+d.url:d.error||'Error'};}catch{}}
  loadOps();addCabinEditor();addControls();addOwnerTools();addHistory();addPhotoEditor();addReservationFilters();addDashboard();
})();
